					reason = "User cancelled";
					accepted = executor.rejectPermission ? await withClawTimeout(executor.rejectPermission(agentSessionId, requestId, reason), CLAW_PERMISSION_DISPATCH_TIMEOUT_MS, `Wechatmp permission ${requestId}`) : false;
