		if (!chatId) throw new Error("deliverWechatmpPermissionRequest: missing chatId in replyContext");
		const { endpoint, headers, userId } = this.resolveApiContext();
		if (!userId) throw new Error("deliverWechatmpPermissionRequest: missing userId");
		let rawInputStr = event.rawInput;
