/**
* marketplaces/local-marketplace.ts · 本地内置推荐包（zip marketplace）实现。
*
* 纯搬家自 `_legacy-archive/service.legacy.ts`：
*   - L327-L381 · 内联的 getMarketplaceSkillContent / getMarketplaceSkills
*   - L645-L736 · 内联的 installMarketplaceSkill（走 enqueueInstall）
*
* LocalMarketplace 特点：
*   - 数据源是**本地** `~/.workbuddy/skills-marketplace/` 目录（由
*     `BuiltinSkillMarketplaceUpdater` 在启动时从 product 配置定期下载 zip 解压而来）
*   - 首次访问会 `await updater.waitForReady()` 触发懒加载下载
*   - 安装其实是本地 cp（从 marketplace dir → userSkillsDir）
*   - meta 文件名：`_skillhub_meta.json`（与 BuiltinMarket / SkillHub 共用），source: 'marketplace'
*   - Web 端没有这个概念（没有本地目录）
*/
function createLocalMarketplaceSkillHandlers(ctx) {
	const { marketplaceDir, userSkillsDir, ensureMarketplaceReady, enqueueInstall } = ctx;
	return {
		getMarketplaceSkillContent: async (params) => {
			await ensureMarketplaceReady();
			let dirName = params.skillName;
			const manifest = require_log_acl_guard.readLocalMarketplaceManifest(marketplaceDir);
			if (manifest?.skills) {
				const matched = manifest.skills.find((s) => s.name === params.skillName);
				if (matched?.source) dirName = matched.source;
			}
			const skillDir = require_log_acl_guard.findMarketplaceSkillDir(marketplaceDir, dirName);
			if (!skillDir) return {
				content: "",
				error: `Skill "${params.skillName}" not found in marketplace`
			};
			const skillMdPath = node_path.join(skillDir, "SKILL.md");
			if (!node_fs.existsSync(skillMdPath)) return {
				content: "",
				error: "SKILL.md not found"
			};
			try {
				return { content: node_fs.readFileSync(skillMdPath, "utf-8") };
			} catch (error) {
				return {
					content: "",
					error: error instanceof Error ? error.message : String(error)
				};
			}
		},
		getMarketplaceSkills: async () => {
			await ensureMarketplaceReady();
			await require_log_acl_guard.ensureDir(marketplaceDir);
			const iconsDir = node_path.join(marketplaceDir, "icons");
			const manifest = require_log_acl_guard.readLocalMarketplaceManifest(marketplaceDir);
			if (manifest?.skills) return {
				results: manifest.skills.map((s) => ({
					...s,
					iconUrl: require_log_acl_guard.resolveLocalIconPath(iconsDir, s.source) ?? require_log_acl_guard.resolveLocalIconPath(iconsDir, s.name) ?? s.iconUrl
				})),
				tagCategories_zh: manifest.tags_zh,
				tagCategories_en: manifest.tags_en
			};
			return { results: require_log_acl_guard.scanMarketplaceSkills(marketplaceDir).map((s) => ({
				...s,
				iconUrl: require_log_acl_guard.resolveLocalIconPath(iconsDir, s.source) ?? require_log_acl_guard.resolveLocalIconPath(iconsDir, s.name) ?? s.iconUrl
			})) };
		},
		installMarketplaceSkill: async (params) => enqueueInstall(async () => {
			await ensureMarketplaceReady();
			const skillName = params.skillName;
			const maxRetries = 2;
			const manifestEntry = require_log_acl_guard.readLocalMarketplaceManifest(marketplaceDir)?.skills?.find((s) => s.name === skillName);
			const source = manifestEntry?.source ?? skillName;
			const version = manifestEntry?.version;
			const baseDirName = sanitizePathSegment(skillName);
			const existingDirName = await findInstalledDirByMetaIndexed(userSkillsDir, "_skillhub_meta.json", "marketplace", [(meta) => typeof meta.name === "string" && meta.name === skillName, (meta) => typeof meta.iconSource === "string" && !!source && meta.iconSource === source]);
			const targetDirName = existingDirName ?? require_log_acl_guard.resolveInstallTargetDirName(userSkillsDir, baseDirName, "local", "_skillhub_meta.json", "marketplace");
			const isInPlaceUpdate = !!existingDirName;
			for (let attempt = 0; attempt <= maxRetries; attempt++) {
				const sourceDir = require_log_acl_guard.findMarketplaceSkillDir(marketplaceDir, source) ?? require_log_acl_guard.findMarketplaceSkillDir(marketplaceDir, skillName);
				if (!sourceDir) return {
					success: false,
					skillName,
					errorMessage: `Skill "${skillName}" not found in marketplace`
				};
				const targetDir = node_path.join(userSkillsDir, targetDirName);
				try {
					node_fs.mkdirSync(userSkillsDir, { recursive: true });
					let existingInstalledAt;
					const existingMetaPath = node_path.join(targetDir, "_skillhub_meta.json");
					if (node_fs.existsSync(existingMetaPath)) try {
						existingInstalledAt = JSON.parse(node_fs.readFileSync(existingMetaPath, "utf-8")).installedAt;
					} catch {}
					if (node_fs.existsSync(targetDir)) {
						if (isInPlaceUpdate) for (const inner of node_fs.readdirSync(targetDir, { withFileTypes: true })) try {
							require_log_acl_guard.rmSyncWithRetry(node_path.join(targetDir, inner.name));
						} catch {}
						else require_log_acl_guard.rmSyncWithRetry(targetDir);
					}
					require_log_acl_guard.copyDirectoryWithRetry(sourceDir, targetDir);
					try {
						node_fs.writeFileSync(node_path.join(targetDir, "_skillhub_meta.json"), JSON.stringify({
							name: skillName,
							installedAt: existingInstalledAt ?? Date.now(),
							source: "marketplace",
							iconSource: manifestEntry?.source,
							version
						}, null, 2));
					} catch {}
					await noteInstalledSkillDir(userSkillsDir, targetDirName);
					return {
						success: true,
						skillName,
						installedPath: node_path.join(userSkillsDir, targetDirName, "SKILL.md")
					};
				} catch (error) {
					const code = error.code;
					if (!(() => {
						try {
							return node_fs.existsSync(sourceDir);
						} catch {
							return false;
						}
					})() && (code === "ENOENT" || code === "EINVAL") && attempt < maxRetries) {
						console.warn(`${require_log_acl_guard.TAG} Source directory vanished during install (${code}), retrying (${attempt + 1}/${maxRetries})...`);
						if (node_fs.existsSync(targetDir)) try {
							require_log_acl_guard.rmSyncWithRetry(targetDir);
						} catch {}
						await new Promise((resolve) => setTimeout(resolve, 200));
						continue;
					}
					if (node_fs.existsSync(targetDir)) try {
						require_log_acl_guard.rmSyncWithRetry(targetDir);
					} catch {}
					return {
						success: false,
						skillName,
						errorMessage: error instanceof Error ? error.message : String(error)
					};
				}
			}
			return {
				success: false,
				skillName,
				errorMessage: `Install failed after ${maxRetries} retries`
			};
		})
	};
}
/**
* 将 skill 显示名清洗为可安全用作文件系统目录名的字符串。
*
* Windows 路径禁止 `<>:"/\|?*` 以及 \x00-\x1F 控制字符，且不允许以点或空格结尾。
* macOS/Linux 只禁止 `/` 和 NUL，但为了跨平台复用（用户可能把 `.workbuddy`
* 目录放到同步盘上被 Windows 侧访问），统一执行最严格的 Windows 规则。
*
* 行为：
* - 非法字符替换为 `_`
* - 去除首尾空白，去除末尾的点和空格（Windows 下这类结尾会被截断）
* - 若清洗后为空（极端情况），退化为 `skill`
*/
function sanitizePathSegment(name) {
	if (!name) return "skill";
	return name.replace(/[<>:"/\\|?*\x00-\x1F]/g, "_").trim().replace(/[. ]+$/g, "") || "skill";
}
