	/**
	* 项目任务列表 = 云端协同任务 ∪ 本地任务（SessionManager 中带 projectId 的 SessionRecord）。
	*
	* 融合规则（仅 Desktop 注入 sessionManager 时生效，Web 端纯云端）：
	* - `params.origin` 为 `teams` / `teams_scheduler` 时：仅返回云端（本地来源是 'local'，互斥）
	* - `params.origin` 为 `'local'` 时：仅返回本地任务（跳过云端请求，本地自身也按 page/size 分页）
	* - `params.scope === 'shared'` 时：仅返回云端（本地任务永远是当前用户私有）
	* - 其他情况：两段各自已按 lastActivityAt desc 有序，**归并成全局有序虚拟列表后整体
	*   分页**：全局第 p 页（size s）取虚拟列表 `[(p-1)*s, p*s)` 窗口，全局按时间降序、
	*   由最近开始排；`total = cloud.total + localCount`，保证前端页码 / totalPages 数学一致。
	*
	*   issue #92665：旧实现把**全量本地任务**并入每一页再混排，导致「翻页后本地任务
	*   永远不变 / 内容像追加在上一页后面」（每页 items = 全部本地 + 一页云端，页码却按
	*   total/size 计算）。归并窗口分页后每页恰好 size 条。
	*
	*   云端按需批量拉取（单批 100 条 = 后端单页上限 maxListProjectConvsSize）：首批必拉
	*   ——归并需要两段头部做时间对比，顺带拿 cloudTotal 供页码计算；窗口较深（如全部
	*   云端任务都比本地新）、已拉批次不够覆盖窗口时再按需追加批次。
	*
	* 失败兜底：SessionManager 调用抛错时不阻断，仅返回云端结果。
	*/
	async listTasks(projectId, params) {
		this.writeLog(projectId, "listTasks", {
			projectId,
			params
		});
		const sm = this.getSessionManager?.();
		const localOnly = params?.origin === "local";
		if (!sm || params?.origin === "teams" || params?.origin === "teams_scheduler" || params?.scope === "shared") {
			const cloudResult = localOnly ? {
				items: [],
				page: params?.page ?? 1,
				size: params?.size ?? 0,
				total: 0
			} : await listTasks(this.http, projectId, params);
			this.writeLog(projectId, "listTasks:res", cloudResult);
			return cloudResult;
		}
		const localItems = await this.getLocalTaskItems(projectId, params?.title);
		if (localOnly) {
			const size = Math.max(1, params?.size ?? 20);
			const page = Math.max(1, params?.page ?? 1);
			const start = (page - 1) * size;
			const result = {
				items: localItems.slice(start, start + size),
				page,
				size,
				total: localItems.length
			};
			this.writeLog(projectId, "listTasks:res", {
				total: result.total,
				localCount: localItems.length
			});
			return result;
		}
		if (localItems.length === 0) {
			const cloudResult = await listTasks(this.http, projectId, params);
			this.writeLog(projectId, "listTasks:res", cloudResult);
			return cloudResult;
		}
		const size = Math.max(1, params?.size ?? 20);
		const page = Math.max(1, params?.page ?? 1);
		const start = (page - 1) * size;
		const end = start + size;
		const CLOUD_BATCH_REQUEST_SIZE = 100;
		const activityOf = (t) => Date.parse(t.lastActivityAt || t.createdAt) || 0;
		let cloudTotal = 0;
		const cloudItems = [];
		let cloudBatchCount = 0;
		/** 已请求的云端页累计（按各批响应实际 size 换算页码）。 */
		let cloudFetched = 0;
		const fetchNextCloudBatch = async () => {
			const batchPageSize = cloudBatchCount > 0 && cloudFetched > 0 ? Math.max(1, Math.ceil(cloudFetched / cloudBatchCount)) : CLOUD_BATCH_REQUEST_SIZE;
			const nextPage = cloudBatchCount === 0 ? 1 : Math.floor(cloudFetched / batchPageSize) + 1;
			const r = await listTasks(this.http, projectId, {
				...params,
				page: nextPage,
				size: CLOUD_BATCH_REQUEST_SIZE
			});
			cloudBatchCount += 1;
			const before = cloudItems.length;
			cloudTotal = r.total;
			cloudItems.push(...r.items);
			cloudFetched += Math.max(r.size ?? 0, r.items.length);
			if (r.items.length === 0) cloudTotal = cloudItems.length;
			const tail = cloudItems.slice(before);
			if (tail.length > 1) {
				tail.sort((a, b) => activityOf(b) - activityOf(a));
				cloudItems.splice(before, tail.length, ...tail);
			}
		};
		await fetchNextCloudBatch();
		const window = [];
		let li = 0;
		let ci = 0;
		let produced = 0;
		while (produced < end) {
			const localHead = li < localItems.length ? localItems[li] : void 0;
			const cloudHead = ci < cloudItems.length ? cloudItems[ci] : void 0;
			if (!localHead && !cloudHead) break;
			if (!cloudHead && cloudItems.length < cloudTotal) {
				await fetchNextCloudBatch();
				continue;
			}
			const item = !cloudHead || !!localHead && activityOf(localHead) > activityOf(cloudHead) ? localItems[li++] : cloudItems[ci++];
			produced += 1;
			if (produced > start) window.push(item);
		}
		const result = {
			items: window,
			page,
			size,
			total: cloudTotal + localItems.length
		};
		this.writeLog(projectId, "listTasks:res", {
			total: result.total,
			localCount: localItems.length,
			cloudTotal,
			cloudBatches: cloudBatchCount,
			windowItems: window.length
		});
		return result;
	}
	/**
	* 从 SessionManager 读取当前用户在该项目下的本地任务（带 projectId 的 SessionRecord），
	* 映射成 TaskConversation。SessionManager 调用失败时返回空数组（best-effort，不阻断云端结果）。
	*/
	async getLocalTaskItems(projectId, titleFilter) {
		const sm = this.getSessionManager?.();
		if (!sm) return [];
		let localRecords;
		try {
			const userId = this.getCurrentUserId?.();
			localRecords = await sm.listSessionRecords({
				userId,
				filters: [{
					field: "projectId",
					value: projectId
				}]
			});
		} catch {
			return [];
		}
		const keyword = titleFilter?.trim().toLowerCase();
		return localRecords.filter((record) => !!record.projectId && record.projectId === projectId).filter((record) => {
			if (!keyword) return true;
			return (record.name ?? "").toLowerCase().includes(keyword);
		}).map((record) => sessionRecordToTaskConversation(record)).sort((a, b) => {
			const ta = Date.parse(a.lastActivityAt || a.createdAt) || 0;
			return (Date.parse(b.lastActivityAt || b.createdAt) || 0) - ta;
		});
	}
