	async generateHandoffSummary(params) {
		const entry = this.boxUrlResolver.tryGet(params.conversationId);
		if (!entry) throw new Error("generateHandoffSummary: no boxUrl cached, connectTask must be called first");
		this.writeLog(params.projectId, "handoffSummary:req", {
			conversationId: params.conversationId,
			sessionId: params.sessionId,
			language: params.language
		});
		try {
			const result = await forkQuery(entry.boxUrl, {
				sourceSessionId: params.sessionId,
				sessionIdPrefix: "handoff-summary-",
				systemPrompt: buildHandoffSummarySystemPrompt(params.language),
				prompt: HANDOFF_SUMMARY_USER_PROMPT,
				timeoutMs: 3e5
			}, entry.token);
			this.writeLog(params.projectId, "handoffSummary:res", {
				newSessionId: result.newSessionId,
				durationMs: result.durationMs,
				resultLen: result.result.length
			});
			return {
				summary: result.result,
				newSessionId: result.newSessionId,
				durationMs: result.durationMs
			};
		} catch (err) {
			this.writeLog(params.projectId, "handoffSummary:error", { error: String(err) });
			throw err;
		}
	}
