		invalidateDaemonProxyCache: () => require_proxy_agents.invalidateProxyAgentCache(),
		getFallbackTestEndpoint: () => input.fallbackProxyTestEndpoint,
		resolveTrustedCAs: () => require_proxy_agents.resolveTrustedCAs(),
		onProxyModeChanged: require_log_acl_guard.setUserProxyMode,
