//#region ../../packages/workbuddy-server/src/agent-harness/mcp/builtin-tools/tool-abort.ts
/**
* 把「MCP 调用方取消」与「本地超时兜底」合成一个 AbortSignal。
*
* 调用方取消走的是 MCP 标准通知 `notifications/cancelled`：SDK server 端收到后
* abort 对应请求的 `extra.signal`，`WorkbuddyMcpServer` 已经把它填进
* `BuiltinToolCallContext.signal`。builtin 工具只要把这里返回的 signal 交给
* fetch，用户在 Agent CLI 侧按下停止时，WorkBuddy 这边对上游的请求就会被真正
* 断掉，而不是继续跑满几分钟的超时窗口再把结果丢掉。
*/
var TOOL_ABORT_REASON_TIMEOUT = "tool-timeout";
var TOOL_ABORT_REASON_CANCELLED = "cancelled-by-caller";
function createToolAbort(timeoutMs, callerSignal) {
	const controller = new AbortController();
	const timer = setTimeout(() => controller.abort(TOOL_ABORT_REASON_TIMEOUT), timeoutMs);
	const onCallerAbort = () => controller.abort(TOOL_ABORT_REASON_CANCELLED);
	if (callerSignal?.aborted) onCallerAbort();
	else callerSignal?.addEventListener("abort", onCallerAbort, { once: true });
	let disposed = false;
	return {
		signal: controller.signal,
		get cancelledByCaller() {
			return callerSignal?.aborted === true;
		},
		dispose() {
			if (disposed) return;
			disposed = true;
			clearTimeout(timer);
			callerSignal?.removeEventListener("abort", onCallerAbort);
		}
	};
}
