	try {
		for (;;) {
			const { done, value } = await reader.read();
			if (done) break;
			buffer += decoder.decode(value, { stream: true });
			let separatorIdx;
			while ((separatorIdx = buffer.indexOf("\n\n")) >= 0) {
				const frame = buffer.slice(0, separatorIdx);
				buffer = buffer.slice(separatorIdx + 2);
				const { eventName, dataStr } = parseSseFrame(frame);
				if (!dataStr) continue;
				processSseEvent(eventName, dataStr, state, onProgress);
			}
		}
	} catch (err) {
		if (abort.signal.aborted) throw abortError("stream read");
		throw err;
	} finally {
		abort.dispose();
		await reader.cancel().catch(() => {});
	}
	if (!state.synthesisContent) throw new Error("Backend SSE stream ended without synthesis content");
	return state.synthesisContent;
