function createAgenticSearchTool(authService, productManager) {
	return {
		name: "agentic_search",
		description: "A search-enhancement tool that currently supports financial and investment topics only. Do not use it for non-financial queries. It delegates the query to a built-in remote agent that autonomously plans and performs multi-step searches, then returns a synthesized summary rather than raw search results. This is an expensive operation with significant latency and resource cost. Use it only for complex financial research that requires multi-source retrieval, cross-validation, or synthesis. For simple searches that can be answered with one or a few keyword queries—such as finding a specific news article, announcement, webpage, definition, or explicit fact—use websearch instead. The delegated query must be a single-sentence, high-level search intent that preserves the user's original intent. Include only the target, topic, scope—including a ticker or code when available—and the general research direction. Do not include field lists, column requirements, table formats, sorting rules, or multiple sub-tasks. Avoid scope-expanding phrases such as “search as comprehensively as possible,” “perform detailed research,” or “cover the following aspects,” because broader instructions substantially increase latency and cost. Filtering, sorting, tabulation, and further analysis must be handled by the main agent after receiving the summary. Good example: for “银河电子怎么样”, delegate “研究 A 股银河电子（002519）整体情况”. Bad pattern: expanding the query into a checklist of business, financials, valuation, capital flows, announcements, and analyst reports.",
		inputSchema: {
			type: "object",
			properties: { query: {
				type: "string",
				description: "A one-sentence, high-level financial search intent for the remote agent. Include only the target or topic and the general research direction. Valid examples: “研究 A 股银河电子（002519）整体情况”, “了解贵州茅台近期业绩表现”. Do not include field lists, output formats, sorting rules, or multiple sub-tasks."
			} },
			required: ["query"]
		},
		handler: async (args, context) => {
			const query = args.query;
			if (!query) return {
				content: [{
					type: "text",
					text: "Error: query is required"
				}],
				isError: true
			};
			const bizVia = authService.getAccount()?.enterpriseId?.trim() ? "internal" : "public";
			const token = authService.getToken();
			if (!token) return {
				content: [{
					type: "text",
					text: "Error: No login session credentials found, please login and retry"
				}],
				isError: true
			};
			const url = `${productManager.getEndpoint()}${AGENTIC_SEARCH_API_PATH}`;
			const headers = {
				"Content-Type": "application/json",
				"Authorization": `Bearer ${token}`
			};
			if (context?.requestId) headers["X-Conversation-Request-ID"] = context.requestId;
			try {
				return { content: [{
					type: "text",
					text: await callBackendSse(query, bizVia, url, headers, context?.onProgress, context?.signal)
				}] };
			} catch (error) {
				return {
					content: [{
						type: "text",
						text: `Financial search failed: ${error instanceof Error ? error.message : String(error)}`
					}],
					isError: true
				};
			}
		}
	};
}
