function createSitesUnpublishTool(deps) {
	const { sitesDeployService } = deps;
	return {
		name: "workbuddy_sites_unpublish",
		summary: "Takes a previously published site offline by its local project directory, so the shared link stops working.",
		description: "Unpublish (take offline) a site that was previously published with the App Publishing (sites) capability. After unpublishing, the shared link stops working.\nWHEN TO USE: the user asks to unpublish / take offline / cancel the publish / stop sharing / disable the online link of a project they previously deployed.\nPass the same local project `directory` that was deployed. The tool finds the latest active publish record for that directory and cancels it.\nIf nothing was ever published for that directory, or it is already unpublished, the tool reports that clearly — tell the user accordingly instead of pretending it was taken offline.\nThis is a destructive action (the public link will stop working). If the user was not explicit, confirm with them (in the same language as your reply) before calling this tool.",
		inputSchema: {
			type: "object",
			properties: { directory: {
				type: "string",
				description: "Absolute path to the local project directory that was previously published."
			} },
			required: ["directory"]
		},
		handler: async (args, context) => {
			const directory = args.directory;
			if (!directory) return {
				content: [{
					type: "text",
					text: "Error: directory parameter is required."
				}],
				isError: true
			};
			try {
				const result = await sitesDeployService.unpublishSite(directory);
				const name = result.title || directory;
				let message;
				switch (result.status) {
					case "unpublished":
						message = `已取消发布「${name}」，原分享链接已失效。`;
						break;
					case "already_unpublished":
						message = `「${name}」当前已是未发布状态，无需重复取消发布。`;
						break;
					default: message = `未找到该目录的发布记录，可能从未发布过：${directory}。`;
				}
				return { content: [{
					type: "text",
					text: JSON.stringify({
						type: "sites_unpublish_result",
						status: result.status,
						message
					})
				}] };
			} catch (error) {
				return {
					content: [{
						type: "text",
						text: `Error unpublishing site: ${error instanceof Error ? error.message : String(error)}`
					}],
					isError: true
				};
			}
		}
	};
}
