var TOOL_NAME = "agent_mail_upload_attachment";
var UPLOAD_TIMEOUT_MS = 6e4;
function errorResult(message) {
	return {
		content: [{
			type: "text",
			text: JSON.stringify({ error: message })
		}],
		isError: true
	};
}
function successResult(data) {
	return { content: [{
		type: "text",
		text: JSON.stringify(data)
	}] };
}
function createUploadAttachmentTool(deps) {
	return {
		name: TOOL_NAME,
		description: "Upload a local file as an Agent Mail email attachment. This tool is exclusively for the Agent Mail service — do NOT use it for other purposes. Returns a file_id that can be referenced in agentmail send_mail to attach the file to an outgoing email. The file_path must be an absolute path to an existing file.",
		inputSchema: {
			type: "object",
			properties: { file_path: {
				type: "string",
				description: "Absolute path to the file to upload as an Agent Mail attachment."
			} },
			required: ["file_path"]
		},
		handler: async (args) => {
			const mailStatus = await getAgentMailStatus(deps);
			if (mailStatus && mailStatus.status !== "active") return buildAgentmailUnavailableResult(mailStatus.status, mailStatus.alias);
			const filePath = args.file_path;
			if (typeof filePath !== "string" || !filePath.trim()) return errorResult("file_path is required and must be a non-empty string.");
			if (!(0, path.isAbsolute)(filePath)) return errorResult("file_path must be an absolute path.");
			if (!resolveBuiltinAgentlyCliPath(deps)) return errorResult("Attachment upload service is unavailable. The required CLI component is missing.");
			try {
				if (!(await (0, fs_promises.stat)(filePath)).isFile()) return errorResult(`Path is not a regular file: ${filePath}`);
			} catch {
				return errorResult(`File does not exist or is not accessible: ${filePath}`);
			}
			let token;
			try {
				token = await getAgentMailAccessToken(deps);
			} catch (err) {
				return errorResult(`Failed to obtain access token: ${err instanceof Error ? err.message : String(err)}`);
			}
			const cwd = (0, path.dirname)(filePath);
			const relativeFile = `./${(0, path.basename)(filePath)}`;
			try {
				const result = await execAgentlyCli([
					"attachment",
					"+upload",
					"--file",
					relativeFile
				], {
					cwd,
					timeoutMs: UPLOAD_TIMEOUT_MS,
					token,
					resolveBundledAsset: deps.resolveBundledAsset
				});
				if (!result.ok) return errorResult(result.error || "Upload failed (CLI returned ok=false).");
				return successResult(result.data ?? { message: "Upload succeeded but no data returned." });
			} catch (err) {
				return errorResult(`Upload failed: ${err instanceof Error ? err.message : String(err)}`);
			}
		}
	};
}
